class ModelManager:
    def __init__(self):
        self.registry_path = MODELS_REGISTRY_FILE
        self.models = self.load_registry()
        self.pretrained_models_dir = config_manager.get("pretrained_models_dir")

    def initialize_registry(self):
        """Creates a new registry with the standard flat list of YOLO models."""
        print("Initializing new model registry...")
        registry = {}
        for model_file, model_name in AVAILABLE_YOLO_MODELS.items():
            registry[model_file] = {"name": model_name, "path": model_file, "type": "yolo"}

        # Add Florence-2
        registry["florence-2-base"] = {
            "name": "Florence-2 (Auto-Labeling)",
            "path": "microsoft/Florence-2-base",
            "type": "florence"
        }

        # Add CLAP
        registry["clap-audio"] = {
            "name": "CLAP (Audio Detection)",
            "path": "laion/clap-htsat-fused",
            "type": "clap"
        }

        # Set a default model name
        if "yolov8n.pt" in registry:
            registry["yolov8n.pt"]["name"] = "YOLOv8-Nano (Default)"
        return registry

    def load_registry(self):
        """Loads the model registry, creating it if it doesn't exist."""
        if os.path.exists(self.registry_path):
            with open(self.registry_path, "r") as f:
                data = json.load(f)
                # Migration: Add 'type' if missing
                dirty = False
                for key, details in data.items():
                    if "type" not in details:
                        details["type"] = "yolo" # Default to old behavior
                        dirty = True

                # Ensure Florence is present
                if "florence-2-base" not in data:
                    data["florence-2-base"] = {
                        "name": "Florence-2 (Auto-Labeling)",
                        "path": "microsoft/Florence-2-base",
                        "type": "florence"
                    }
                    dirty = True

                # Ensure CLAP is present
                if "clap-audio" not in data:
                    data["clap-audio"] = {
                        "name": "CLAP (Audio Detection)",
                        "path": "laion/clap-htsat-fused",
                        "type": "clap"
                    }
                    dirty = True

                if dirty:
                    self.save_registry(data)
                return data
        else:
            new_registry = self.initialize_registry()
            self.save_registry(new_registry)
            return new_registry

    def save_registry(self, registry_data=None):
        """Saves the current model registry to disk."""
        data_to_save = registry_data if registry_data is not None else self.models
        with open(self.registry_path, "w") as f:
            json.dump(data_to_save, f, indent=4)

    def get_model_names(self):
        """Returns a list of friendly names for all registered models."""
        return sorted([details["name"] for details in self.models.values()])

    def get_model_path(self, friendly_name):
        """Finds the path of a model from its friendly name."""
        for key, details in self.models.items():
            if details["name"] == friendly_name:
                model_path = details["path"]
                # If path is just a filename (yolo), resolve to pretrained dir
                # If it's a huggingface ID (florence), return as is
                if details.get("type") == "yolo" and not os.path.isabs(model_path):
                     return os.path.join(self.pretrained_models_dir, model_path)
                return model_path
        return None

    def get_model_type(self, friendly_name):
        """Returns the type of the model (yolo, florence, etc)."""
        for key, details in self.models.items():
            if details["name"] == friendly_name:
                return details.get("type", "yolo")
        return "yolo"

    def register_model(self, path_to_model, name=None, model_type="yolo"):
        """Adds a new custom model to the registry."""
        if not os.path.exists(path_to_model):
            print(f"Warning: Model path does not exist: {path_to_model}")
            return

        key = os.path.abspath(path_to_model)
        if key in self.models:
            print(f"Model at path {key} is already registered.")
            return

        if name is None:
            name = f"Custom Model ({os.path.basename(path_to_model)})"

        self.models[key] = {"name": name, "path": key, "type": model_type}
        self.save_registry()
        print(f"Registered new model: {name}")

"""
Base adapter defines the interface the GUI will use.
All adapters must implement: load(), predict(image_path), retrain(trigger_data), and name property.
"""
from abc import ABC, abstractmethod


class BaseAdapter(ABC):
    def __init__(self, cfg):
        self.cfg = cfg

    @abstractmethod
    def load(self):
        """Load model weights or initialize model."""
        pass

    @abstractmethod
    def predict(self, image_path, **kwargs):
        """Return a list of predictions in unified format:
        [{"label": str, "x1": int, "y1": int, "x2": int, "y2": int, "confidence": float}, ...]
        """
        pass

    @abstractmethod
    def retrain(self, annotations):
        """Trigger retraining/fine-tuning given new annotations. May be synchronous or spawn a job."""
        pass

    @property
    @abstractmethod
    def name(self):
        pass

