import os
import json
from collections import Counter

class DatasetExplorer:
    def __init__(self, project):
        self.project = project

    def get_stats(self):
        """
        Calculates statistics for the current project.
        Returns a dictionary with keys: 'total_files', 'annotated_files', 'class_distribution'.
        """
        annotations = self.project.session.get("annotations", {})

        total_files = 0
        annotated_files = 0
        label_counts = Counter()

        # Check modality to determine how to count files
        modality = self.project.config.get("modality", "vision")
        source_dir = ""

        if modality == "audio":
            source_dir = self.project.audio_dir_source
        elif modality == "video":
            source_dir = self.project.image_dir_source # Video reuses image_dir_source key currently
        else:
            source_dir = self.project.image_dir_source

        if os.path.exists(source_dir):
            total_files = len(os.listdir(source_dir))

        for filename, data in annotations.items():
            # Vision/Audio structure: data = {"objects": [...]}
            # Video structure: data = { "frame_idx": {"objects": [...]}, ... }

            if modality == "video":
                # Check if video has any annotations in any frame
                has_annotations = False
                for frame_key, frame_data in data.items():
                    objects = frame_data.get("objects", [])
                    if objects:
                        has_annotations = True
                        for obj in objects:
                            label_counts[obj.get("label", "unknown")] += 1
                if has_annotations:
                    annotated_files += 1
            else:
                objects = data.get("objects", [])
                if objects:
                    annotated_files += 1
                    for obj in objects:
                        label_counts[obj.get("label", "unknown")] += 1

        return {
            "total_files": total_files,
            "annotated_files": annotated_files,
            "class_distribution": dict(label_counts)
        }

