import tkinter as tk
from tkinter import ttk

class ThemeManager:
    """
    Manages the application's visual theme (Dark/Light).
    """

    THEMES = {
        "dark": {
            "bg": "#2c2c2c",
            "fg": "#ffffff",
            "canvas_bg": "#1e1e1e",
            "panel_bg": "#333333",
            "entry_bg": "#404040",
            "entry_fg": "#ffffff",
            "button_bg": "#505050",
            "button_fg": "#ffffff",
            "highlight": "#00acc1"
        },
        "light": {
            "bg": "#f0f0f0",
            "fg": "#000000",
            "canvas_bg": "#e0e0e0",
            "panel_bg": "#f0f0f0",
            "entry_bg": "#ffffff",
            "entry_fg": "#000000",
            "button_bg": "#e0e0e0",
            "button_fg": "#000000",
            "highlight": "#007acc"
        }
    }

    @staticmethod
    def apply_theme(root, theme_name="dark"):
        theme = ThemeManager.THEMES.get(theme_name, ThemeManager.THEMES["dark"])

        style = ttk.Style(root)
        style.theme_use('clam')

        # Configure global options
        root.configure(bg=theme["bg"])

        # Configure generic widgets manually for non-ttk
        # Note: This is a recursive function to apply to all current widgets
        def apply_recursive(widget):
            try:
                w_type = widget.winfo_class()
                if w_type in ("Frame", "LabelFrame", "Toplevel", "Tk"):
                    widget.configure(bg=theme["bg"])
                    if hasattr(widget, "configure") and "fg" in widget.keys():
                         widget.configure(fg=theme["fg"])
                elif w_type == "Label":
                    widget.configure(bg=theme["bg"], fg=theme["fg"])
                elif w_type == "Button":
                    widget.configure(bg=theme["button_bg"], fg=theme["button_fg"])
                elif w_type == "Entry" or w_type == "Listbox":
                    widget.configure(bg=theme["entry_bg"], fg=theme["entry_fg"])
                elif w_type == "Canvas":
                     # Don't overwrite specific canvas bgs if set (like video)
                     pass 
            except:
                pass

            for child in widget.winfo_children():
                apply_recursive(child)

        apply_recursive(root)
        return theme

import os
import json
import customtkinter as ctk

class SettingsManager:
    _instance = None

    DEFAULT_SETTINGS = {
        "appearance_mode": "Dark",  # Dark, Light, System
        "color_theme": "blue",      # blue, dark-blue, green
        "autosave_interval": 5,     # minutes
        "show_confidence_scores": True,
        "default_modality": "vision",
        "device_target": "cuda",    # cuda, cpu
        "ui_scale": 1.0,
    }

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super(SettingsManager, cls).__new__(cls)
            cls._instance.config_dir = os.path.join(os.path.expanduser("~"), ".neuroloop")
            cls._instance.config_file = os.path.join(cls._instance.config_dir, "global_settings.json")
            cls._instance.settings = cls._instance.DEFAULT_SETTINGS.copy()
            cls._instance.load()
        return cls._instance

    def load(self):
        if os.path.exists(self.config_file):
            try:
                with open(self.config_file, "r") as f:
                    saved = json.load(f)
                    self.settings.update(saved)
            except Exception as e:
                print(f"Failed to load settings: {e}")

        # Apply Appearance immediately
        ctk.set_appearance_mode(self.settings["appearance_mode"])
        ctk.set_default_color_theme(self.settings["color_theme"])
        ctk.set_widget_scaling(self.settings["ui_scale"])

    def save(self):
        os.makedirs(self.config_dir, exist_ok=True)
        with open(self.config_file, "w") as f:
            json.dump(self.settings, f, indent=4)

    def get(self, key):
        return self.settings.get(key, self.DEFAULT_SETTINGS.get(key))

    def set(self, key, value):
        self.settings[key] = value
        self.save()

        # Apply Immediate Changes
        if key == "appearance_mode":
            ctk.set_appearance_mode(value)
        elif key == "ui_scale":
            ctk.set_widget_scaling(value)
